WITH base AS (SELECT *, TRIM(event_type) AS clean_event_type FROM web_events WHERE event_time >= DATE '2023-09-29' AND page IS NOT NULL), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM base), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY session_start_flag DESC, id) AS dedup_rank FROM islands QUALIFY dedup_rank = 1), cleaned AS (SELECT id, event_type, event_time, duration_sec, clean_event_type, session_start_flag, burst_id, YEAR(event_time) AS event_time_year, COALESCE(page, 'Unknown') AS page_filled FROM deduped WHERE page IS NOT NULL AND duration_sec >= 198) SELECT id, event_type, event_time, clean_event_type, session_start_flag, burst_id, event_time_year, page_filled FROM cleaned ORDER BY event_type DESC, event_time_year DESC;
